	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"version" integer NOT NULL,
	"body" jsonb NOT NULL,
	"created_by_user_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "claims_version_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "claims_version_version_key" UNIQUE("tenant_id","version"),
	CONSTRAINT "claims_version_version" CHECK ("claims_version"."version" >= 1),
	CONSTRAINT "claims_version_body" CHECK (jsonb_typeof("claims_version"."body") = 'object')
);
