-- Grants. An import replaces a day of search figures whole (delete and insert), so those two
-- tables give the runtime DELETE, as 0037's day tables do. Nothing else here is ever deleted:
-- a page is unpublished, a redirect re-pointed, a source's state updated, a report read, an
-- action decided, a reply decided or marked posted. Versions and the publish log are insert only.
GRANT SELECT, INSERT, UPDATE ON search_source, content_page, content_redirect, marketing_report, marketing_report_action, forum_thread, forum_reply TO cs_runtime;
GRANT SELECT, INSERT, DELETE ON search_query_daily, search_page_daily TO cs_runtime;
GRANT SELECT, INSERT ON content_version, content_publish, claims_version TO cs_runtime;
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['search_source', 'search_query_daily', 'search_page_daily', 'content_page', 'content_version', 'content_publish', 'content_redirect', 'claims_version', 'marketing_report', 'marketing_report_action', 'forum_thread', 'forum_reply'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO PUBLIC '
      'USING (tenant_id = any(app_tenant_ids())) '
      'WITH CHECK (tenant_id = any(app_tenant_ids()))', t);
    -- Which pack owns a table (docs/plan.md §1.12, §1.63), as in 0037.
    EXECUTE format('COMMENT ON TABLE %I IS %L', t, 'pack:marketing');
  END LOOP;
END
$$;

-- Immutable history (invariant 3): a page's path and authorship, a version, a publish, a claims
-- list, a report's body and sources, an action's text and a reply's body never change, and none
-- of these rows is ever deleted. The columns named may still change.
CREATE TRIGGER content_page_immutable BEFORE UPDATE OR DELETE ON content_page
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except('status', 'live_version_id');
CREATE TRIGGER content_version_immutable BEFORE UPDATE OR DELETE ON content_version
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except();
CREATE TRIGGER content_publish_append_only BEFORE UPDATE OR DELETE ON content_publish
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except();
CREATE TRIGGER claims_version_immutable BEFORE UPDATE OR DELETE ON claims_version
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except();
CREATE TRIGGER marketing_report_immutable BEFORE UPDATE OR DELETE ON marketing_report
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except('read_at', 'read_by_user_id');
CREATE TRIGGER marketing_report_action_immutable BEFORE UPDATE OR DELETE ON marketing_report_action
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except('decision', 'decided_by_user_id', 'decided_at');
CREATE TRIGGER forum_reply_immutable BEFORE UPDATE OR DELETE ON forum_reply
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except('status', 'poster_user_id', 'decided_by_user_id', 'decided_at', 'posted_at', 'reason');

-- A page's live version is one of its own versions, of the same client. Its foreign key has one
-- column, as agent.live_version_id's does, so the purge (packages/db/src/purge.ts) can clear it
-- and delete the page and its versions; this check stands in for the composite key.
CREATE OR REPLACE FUNCTION content_page_live_version_check() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.live_version_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM content_version v
    WHERE v.id = NEW.live_version_id AND v.page_id = NEW.id AND v.tenant_id = NEW.tenant_id
  ) THEN
    RAISE EXCEPTION 'content_page % live version % is not one of its own', NEW.id, NEW.live_version_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER content_page_live_version BEFORE INSERT OR UPDATE OF live_version_id ON content_page
  FOR EACH ROW EXECUTE FUNCTION content_page_live_version_check();
